    function hexToRgb(hex) {
  const h = hex.replace("#", "");
  const full = h.length === 3 ? h.split("").map((c) => c + c).join("") : h;
  const n = parseInt(full.slice(0, 6), 16);
  return { r: (n >> 16) & 255, g: (n >> 8) & 255, b: n & 255 };
}
    function rgbToHex({ r, g, b }) {
  const c = (v) => Math.max(0, Math.min(255, Math.round(v))).toString(16).padStart(2, "0");
  return `#${c(r)}${c(g)}${c(b)}`;
}
    function mix(a, b, t) {
  const x = hexToRgb(a);
  const y = hexToRgb(b);
  return rgbToHex({ r: x.r + (y.r - x.r) * t, g: x.g + (y.g - x.g) * t, b: x.b + (y.b - x.b) * t });
}
    function lighten(hex, t) { return mix(hex, "#FFFFFF", t); }
    function darken(hex, t) { return mix(hex, "#000000", t); }
    function alpha(hex, a) {
  const { r, g, b } = hexToRgb(hex);
  const aa = Math.max(0, Math.min(255, Math.round(a * 255))).toString(16).padStart(2, "0");
  return `#${hex.replace("#", "").length === 6 ? hex.slice(1) : hex.slice(1, 7)}${aa}`;
}
    function resolveSpec(spec, palette) {
  return typeof spec === "function" ? spec(palette) : palette[spec];
}
